import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it("single cell dies -- [(0,0)] → []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });
  it("underpopulation: live cell with 1 neighbor dies -- [(0,1), (1,1)] → []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });
  it("survival: live cells with 2 neighbors live on -- [(0,0), (1,0), (0,1)] keep originals", () => {
    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
    expect(result).toEqual(expect.arrayContaining([[0, 0], [1, 0], [0, 1]]));
  });
  it.todo("reproduction: dead cell with exactly 3 neighbors becomes alive -- [(0,0), (1,0), (0,1)] → includes (1,1)");
  it.todo("overpopulation: live cell with more than 3 neighbors dies -- center (1,1) dies");
  it.todo("block still life -- [(0,0), (1,0), (0,1), (1,1)] → unchanged");
  it.todo("blinker oscillator Gen 0 → Gen 1 -- [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]");
  it.todo("blinker oscillator Gen 1 → Gen 2 -- [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]");
});

