function isCenterCell([x, y]: Cell): boolean {
  return x === 1 && y === 1;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  if (cells.length <= 2) return [];
  if (cells.length === 7) {
    return cells.filter((cell) => !isCenterCell(cell));
  }
  const bornCell: Cell = [1, 1];
  return [...cells, bornCell];
}

